INSERT INTO repo_subtopics (subtopic_id, name, subtopic_no, description, subtopic_sd_id, review_status, status, version) VALUES ('SUB_COURSE_054_M7_S4', 'remote work', '4', 'remote work: Work performed away from the employer''s usual workplace using communication and digital technologies. In Contemporary Employment Issues, the focus is on the analysis, design, implementation, interpretation, or evaluation of remote work within Labour and Employment Law, particularly where the Contemporary Employment Issues module establishes its technical context.', 'SSD_COURSE_054_M7_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_054_M7_S5', 'compliance systems', '5', 'compliance systems: compliance systems in Environmental Law and Environmental Governance concerns legal rules, institutional mechanisms, duties, procedures, and compliance considerations governing compliance systems. In Contemporary Employment Issues, the focus is on the analysis, design, implementation, interpretation, or evaluation of compliance systems within Environmental Law and Environmental Governance, particularly where the Environmental Governance Practice module establishes its technical context.', 'SSD_COURSE_054_M7_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_055_M1_S1', 'company organs', '1', 'company organs: Corporate bodies such as the board, shareholders, and management through which a company exercises legal powers and makes decisions. In Corporate Governance, the focus is on the analysis, design, implementation, interpretation, or evaluation of company organs within Corporate, Sustainability and ESG Law, particularly where the Corporate Governance module establishes its technical context.', 'SSD_COURSE_055_M1_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_055_M1_S2', 'governance structures', '2', 'governance structures: governance structures in Corporate, Sustainability and ESG Law concerns legal rules, institutional mechanisms, duties, procedures, and compliance considerations governing governance structures. In Corporate Governance, the focus is on the analysis, design, implementation, interpretation, or evaluation of governance structures within Corporate, Sustainability and ESG Law, particularly where the Corporate Governance module establishes its technical context.', 'SSD_COURSE_055_M1_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_055_M1_S3', 'shareholder rights', '3', 'shareholder rights: Legal rights of shareholders relating to voting, information, dividends, meetings, and other corporate matters. In Corporate Governance, the focus is on the analysis, design, implementation, interpretation, or evaluation of shareholder rights within Corporate, Sustainability and ESG Law, particularly where the Corporate Governance module establishes its technical context.', 'SSD_COURSE_055_M1_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_055_M1_S4', 'disclosure', '4', 'disclosure: Provision or publication of specified information to persons or entities entitled or required to receive it under applicable rules or agreements. In Corporate Governance, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_055_M1_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_055_M2_S1', 'fiduciary duties', '1', 'fiduciary duties: Duties requiring certain corporate decision-makers to act loyally, in good faith, and for proper purposes. In Directors Duties and Accountability, the focus is on the analysis, design, implementation, interpretation, or evaluation of fiduciary duties within Corporate, Sustainability and ESG Law, particularly where the Directors Duties and Accountability module establishes its technical context.', 'SSD_COURSE_055_M2_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_055_M2_S2', 'care', '2', 'care refers to the duty to exercise appropriate care, skill, and diligence in making corporate decisions. In Directors Duties and Accountability, the focus is on the analysis, design, implementation, interpretation, or evaluation of care within Corporate, Sustainability and ESG Law, particularly where the Directors Duties and Accountability module establishes its technical context.', 'SSD_COURSE_055_M2_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_055_M2_S3', 'conflict management', '3', 'conflict management: Processes for identifying, disclosing, assessing, and managing conflicts between corporate duties or interests. In Directors Duties and Accountability, the focus is on the analysis, design, implementation, interpretation, or evaluation of conflict management within Corporate, Sustainability and ESG Law, particularly where the Directors Duties and Accountability module establishes its technical context.', 'SSD_COURSE_055_M2_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_055_M2_S4', 'related-party transactions', '4', 'related-party transactions: Transactions involving a company and a director, officer, shareholder, or other related person or entity. In Directors Duties and Accountability, the focus is on the analysis, design, implementation, interpretation, or evaluation of related-party transactions within Corporate, Sustainability and ESG Law, particularly where the Directors Duties and Accountability module establishes its technical context.', 'SSD_COURSE_055_M2_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_055_M3_S1', 'corporate environmental duties', '1', 'corporate environmental duties: Legal or regulatory responsibilities of companies concerning environmental protection, pollution, resource use, and disclosure. In Environmental and Social Responsibilities, the focus is on the analysis, design, implementation, interpretation, or evaluation of corporate environmental duties within Corporate, Sustainability and ESG Law, particularly where the Environmental and Social Responsibilities module establishes its technical context.', 'SSD_COURSE_055_M3_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_055_M3_S2', 'labour rights', '2', 'labour rights: Employment rights relevant to corporate conduct, including fair treatment, safety, representation, and working conditions. In Environmental and Social Responsibilities, the focus is on the analysis, design, implementation, interpretation, or evaluation of labour rights within Corporate, Sustainability and ESG Law, particularly where the Environmental and Social Responsibilities module establishes its technical context.', 'SSD_COURSE_055_M3_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_055_M3_S3', 'community impacts', '3', 'community impacts: Effects of corporate activities on local communities, including social, economic, environmental, and livelihood effects. In Environmental and Social Responsibilities, the focus is on the analysis, design, implementation, interpretation, or evaluation of community impacts within Corporate, Sustainability and ESG Law, particularly where the Environmental and Social Responsibilities module establishes its technical context.', 'SSD_COURSE_055_M3_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_055_M3_S4', 'supply-chain responsibility', '4', 'supply-chain responsibility: Corporate responsibility for identifying and managing environmental, social, human-rights, and governance risks in supply chains. In Environmental and Social Responsibilities, the focus is on the analysis, design, implementation, interpretation, or evaluation of supply-chain responsibility within Corporate, Sustainability and ESG Law, particularly where the Environmental and Social Responsibilities module establishes its technical context.', 'SSD_COURSE_055_M3_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_055_M4_S1', 'materiality', '1', 'materiality refers to the significance of an ESG matter to an organization''s decisions, impacts, risks, opportunities, or information users, according to the applicable reporting framework. In ESG Disclosure and Reporting, the focus is on the analysis, design, implementation, interpretation, or evaluation of materiality within Corporate, Sustainability and ESG Law, particularly where the ESG Disclosure and Reporting module establishes its technical context.', 'SSD_COURSE_055_M4_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_055_M4_S2', 'non-financial disclosure', '2', 'non-financial disclosure: non-financial disclosure in Corporate, Sustainability and ESG Law concerns legal rules, institutional mechanisms, duties, procedures, and compliance considerations governing non-financial disclosure. In ESG Disclosure and Reporting, the focus is on the analysis, design, implementation, interpretation, or evaluation of non-financial disclosure within Corporate, Sustainability and ESG Law, particularly where the ESG Disclosure and Reporting module establishes its technical context.', 'SSD_COURSE_055_M4_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_055_M4_S3', 'sustainability reporting', '3', 'sustainability reporting: Disclosure of material environmental, social, governance, and sustainability information using applicable reporting requirements or standards. In ESG Disclosure and Reporting, the focus is on the analysis, design, implementation, interpretation, or evaluation of sustainability reporting within Corporate, Sustainability and ESG Law, particularly where the ESG Disclosure and Reporting module establishes its technical context.', 'SSD_COURSE_055_M4_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_055_M4_S4', 'assurance concepts', '4', 'assurance concepts: Principles and processes for obtaining independent confidence in the quality or reliability of reported sustainability information. In ESG Disclosure and Reporting, the focus is on the analysis, design, implementation, interpretation, or evaluation of assurance concepts within Corporate, Sustainability and ESG Law, particularly where the ESG Disclosure and Reporting module establishes its technical context.', 'SSD_COURSE_055_M4_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_055_M5_S1', 'green finance', '1', 'green finance: Financial products or decisions that direct capital while considering environmental or climate objectives and risks. In Sustainable Finance and Corporate Risk, the focus is on the analysis, design, implementation, interpretation, or evaluation of green finance within Corporate, Sustainability and ESG Law, particularly where the Sustainable Finance and Corporate Risk module establishes its technical context.', 'SSD_COURSE_055_M5_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_055_M5_S2', 'climate risk', '2', 'climate risk: Financial, operational, legal, or strategic risk arising from physical climate impacts or the transition to a lower-carbon economy. In Sustainable Finance and Corporate Risk, the focus is on the analysis, design, implementation, interpretation, or evaluation of climate risk within Corporate, Sustainability and ESG Law, particularly where the Sustainable Finance and Corporate Risk module establishes its technical context.', 'SSD_COURSE_055_M5_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_055_M5_S3', 'transition risk', '3', 'transition risk: Risk arising from policy, technology, market, legal, or behavioural changes associated with transition to a lower-carbon economy. In Sustainable Finance and Corporate Risk, the focus is on the analysis, design, implementation, interpretation, or evaluation of transition risk within Corporate, Sustainability and ESG Law, particularly where the Sustainable Finance and Corporate Risk module establishes its technical context.', 'SSD_COURSE_055_M5_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_055_M5_S4', 'due diligence', '4', 'due diligence refers to a structured process for identifying, assessing, preventing, mitigating, tracking, and addressing adverse impacts or risks. In Sustainable Finance and Corporate Risk, the focus is on the analysis, design, implementation, interpretation, or evaluation of due diligence within Corporate, Sustainability and ESG Law, particularly where the Sustainable Finance and Corporate Risk module establishes its technical context.', 'SSD_COURSE_055_M5_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_055_M6_S1', 'compliance programs', '1', 'compliance programs: compliance programs in Corporate, Sustainability and ESG Law concerns legal rules, institutional mechanisms, duties, procedures, and compliance considerations governing compliance programs. In Corporate Compliance and Enforcement, the focus is on the analysis, design, implementation, interpretation, or evaluation of compliance programs within Corporate, Sustainability and ESG Law, particularly where the Corporate Compliance and Enforcement module establishes its technical context.', 'SSD_COURSE_055_M6_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_055_M6_S2', 'investigations', '2', 'investigations: Formal processes for examining suspected misconduct, non-compliance, breaches, or disputed corporate conduct. In Corporate Compliance and Enforcement, the focus is on the analysis, design, implementation, interpretation, or evaluation of investigations within Corporate, Sustainability and ESG Law, particularly where the Corporate Compliance and Enforcement module establishes its technical context.', 'SSD_COURSE_055_M6_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_055_M6_S3', 'whistleblowing', '3', 'whistleblowing: Reporting suspected wrongdoing or misconduct through protected internal or external channels. In Corporate Compliance and Enforcement, the focus is on the analysis, design, implementation, interpretation, or evaluation of whistleblowing within Corporate, Sustainability and ESG Law, particularly where the Corporate Compliance and Enforcement module establishes its technical context.', 'SSD_COURSE_055_M6_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_055_M6_S4', 'sanctions', '4', 'sanctions: Legal or regulatory penalties imposed for specified corporate, environmental, reporting, or governance violations. In Corporate Compliance and Enforcement, the focus is on the analysis, design, implementation, interpretation, or evaluation of sanctions within Corporate, Sustainability and ESG Law, particularly where the Corporate Compliance and Enforcement module establishes its technical context.', 'SSD_COURSE_055_M6_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_055_M7_S1', 'greenwashing', '1', 'greenwashing: Misleading or unsupported claims about the environmental or sustainability performance of a product, activity, or organisation. In ESG Legal Practice and Disputes, the focus is on the analysis, design, implementation, interpretation, or evaluation of greenwashing within Corporate, Sustainability and ESG Law, particularly where the ESG Legal Practice and Disputes module establishes its technical context.', 'SSD_COURSE_055_M7_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_055_M7_S2', 'stakeholder claims', '2', 'stakeholder claims: Legal or formal claims brought by affected stakeholders concerning corporate conduct, impacts, rights, or disclosures. In ESG Legal Practice and Disputes, the focus is on the analysis, design, implementation, interpretation, or evaluation of stakeholder claims within Corporate, Sustainability and ESG Law, particularly where the ESG Legal Practice and Disputes module establishes its technical context.', 'SSD_COURSE_055_M7_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_055_M7_S3', 'disclosure liability', '3', 'disclosure liability: disclosure liability in Corporate, Sustainability and ESG Law concerns legal rules, institutional mechanisms, duties, procedures, and compliance considerations governing disclosure liability. In ESG Legal Practice and Disputes, the focus is on the analysis, design, implementation, interpretation, or evaluation of disclosure liability within Corporate, Sustainability and ESG Law, particularly where the ESG Legal Practice and Disputes module establishes its technical context.', 'SSD_COURSE_055_M7_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_055_M7_S4', 'contractual ESG clauses', '4', 'contractual ESG clauses: Contract provisions imposing environmental, social, human-rights, reporting, or governance requirements on counterparties. In ESG Legal Practice and Disputes, the focus is on the analysis, design, implementation, interpretation, or evaluation of contractual ESG clauses within Corporate, Sustainability and ESG Law, particularly where the ESG Legal Practice and Disputes module establishes its technical context.', 'SSD_COURSE_055_M7_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_056_M1_S1', 'classical theory', '1', 'classical theory: Foundational sociological perspectives developed to explain social order, conflict, institutions, and modern social change. In Sociological Theory, the focus is on the analysis, design, implementation, interpretation, or evaluation of classical theory within Sociology, particularly where the Sociological Theory module establishes its technical context.', 'SSD_COURSE_056_M1_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_056_M1_S2', 'functionalism', '2', 'functionalism refers to a sociological perspective that examines how social institutions and practices contribute to the functioning and stability of society. In Sociological Theory, the focus is on the analysis, design, implementation, interpretation, or evaluation of functionalism within Sociology, particularly where the Sociological Theory module establishes its technical context.', 'SSD_COURSE_056_M1_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_056_M1_S3', 'conflict theory', '3', 'conflict theory refers to a perspective that explains social structures and change through unequal power, resources, and competing interests. In Sociological Theory, the focus is on the analysis, design, implementation, interpretation, or evaluation of conflict theory within Sociology, particularly where the Sociological Theory module establishes its technical context.', 'SSD_COURSE_056_M1_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_056_M1_S4', 'symbolic interactionism', '4', 'symbolic interactionism refers to a perspective that explains social life through meanings created and modified through interaction. In Sociological Theory, the focus is on the analysis, design, implementation, interpretation, or evaluation of symbolic interactionism within Sociology, particularly where the Sociological Theory module establishes its technical context.', 'SSD_COURSE_056_M1_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_056_M2_S1', 'family', '1', 'family refers to a social institution organising relationships, care, reproduction, socialisation, and household life. In Social Institutions, the focus is on the analysis, design, implementation, interpretation, or evaluation of family within Sociology, particularly where the Social Institutions module establishes its technical context.', 'SSD_COURSE_056_M2_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_056_M2_S2', 'education', '2', 'education: Structured processes and institutions through which knowledge, skills, values, and capabilities are developed and transmitted across individuals and society. In Social Institutions, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_056_M2_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_056_M2_S3', 'religion', '3', 'religion refers to a social institution involving beliefs, practices, organisations, and meanings related to the sacred or transcendent. In Social Institutions, the focus is on the analysis, design, implementation, interpretation, or evaluation of religion within Sociology, particularly where the Social Institutions module establishes its technical context.', 'SSD_COURSE_056_M2_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_056_M2_S4', 'economy', '4', 'economy refers to the social organisation of production, distribution, exchange, and consumption of goods and services. In Social Institutions, the focus is on the analysis, design, implementation, interpretation, or evaluation of economy within Sociology, particularly where the Social Institutions module establishes its technical context.', 'SSD_COURSE_056_M2_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_056_M2_S5', 'polity', '5', 'polity refers to the institutions and processes through which collective decisions, authority, and power are organised. In Social Institutions, the focus is on the analysis, design, implementation, interpretation, or evaluation of polity within Sociology, particularly where the Social Institutions module establishes its technical context.', 'SSD_COURSE_056_M2_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_056_M2_S6', 'institutional change', '6', 'institutional change: Transformation in the rules, structures, roles, or practices that organise major areas of social life. In Social Institutions, the focus is on the analysis, design, implementation, interpretation, or evaluation of institutional change within Sociology, particularly where the Social Institutions module establishes its technical context.', 'SSD_COURSE_056_M2_S6', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_056_M3_S1', 'culture', '1', 'culture: Shared meanings, symbols, knowledge, practices, and material forms through which groups organise social life. In Culture and Socialization, the focus is on the analysis, design, implementation, interpretation, or evaluation of culture within Sociology, particularly where the Culture and Socialization module establishes its technical context.', 'SSD_COURSE_056_M3_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_056_M3_S2', 'norms', '2', 'norms: Socially shared expectations about appropriate behaviour in particular situations. In Culture and Socialization, the focus is on the analysis, design, implementation, interpretation, or evaluation of norms within Sociology, particularly where the Culture and Socialization module establishes its technical context.', 'SSD_COURSE_056_M3_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_056_M3_S3', 'values', '3', 'values: Shared beliefs about what is desirable, important, or morally appropriate in a society or group. In Culture and Socialization, the focus is on the analysis, design, implementation, interpretation, or evaluation of values within Sociology, particularly where the Culture and Socialization module establishes its technical context.', 'SSD_COURSE_056_M3_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_056_M3_S4', 'identity', '4', 'identity refers to the ways individuals and groups define, experience, and communicate who they are socially. In Culture and Socialization, the focus is on the analysis, design, implementation, interpretation, or evaluation of identity within Sociology, particularly where the Culture and Socialization module establishes its technical context.', 'SSD_COURSE_056_M3_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_056_M3_S5', 'socialization', '5', 'socialization refers to the lifelong process through which people learn social norms, values, roles, and patterns of behaviour. In Culture and Socialization, the focus is on the analysis, design, implementation, interpretation, or evaluation of socialization within Sociology, particularly where the Culture and Socialization module establishes its technical context.', 'SSD_COURSE_056_M3_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_056_M3_S6', 'deviance', '6', 'deviance: Behaviour, conditions, or identities defined as violating socially established norms within a particular context. In Culture and Socialization, the focus is on the analysis, design, implementation, interpretation, or evaluation of deviance within Sociology, particularly where the Culture and Socialization module establishes its technical context.', 'SSD_COURSE_056_M3_S6', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_056_M4_S1', 'class', '1', 'class refers to a social grouping associated with economic position, resources, occupation, and relations to production. In Stratification and Inequality, the focus is on the analysis, design, implementation, interpretation, or evaluation of class within Sociology, particularly where the Stratification and Inequality module establishes its technical context.', 'SSD_COURSE_056_M4_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_056_M4_S2', 'status', '2', 'status refers to a socially recognised position carrying associated expectations, rights, duties, or prestige. In Stratification and Inequality, the focus is on the analysis, design, implementation, interpretation, or evaluation of status within Sociology, particularly where the Stratification and Inequality module establishes its technical context.', 'SSD_COURSE_056_M4_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_056_M4_S3', 'gender', '3', 'gender: Socially organised meanings, roles, expectations, and relations associated with gender categories. In Stratification and Inequality, the focus is on the analysis, design, implementation, interpretation, or evaluation of gender within Sociology, particularly where the Stratification and Inequality module establishes its technical context.', 'SSD_COURSE_056_M4_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_056_M4_S4', 'race/ethnicity as social structure', '4', 'race/ethnicity as social structure: Race and ethnicity treated as socially organised categories that shape identity, opportunity, institutions, and inequality. In Stratification and Inequality, the focus is on the analysis, design, implementation, interpretation, or evaluation of race/ethnicity as social structure within Sociology, particularly where the Stratification and Inequality module establishes its technical context.', 'SSD_COURSE_056_M4_S4', 'Semantically_Audited', 'Active', '4.0') ON CONFLICT DO NOTHING;